window.AUTH=window.AUTH||{};window.AUTH["02-1080"]={"d":"02-1080","id":"2003/02-1080","n":"General Dynamics Land Systems Inc. v. Cline","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States and the Equal Employment Opportunity Commission as amici curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/203561/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/general-dynamics-v-cline-amicus-merits","n":48}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep540/usrep540581/usrep540581.pdf","tr":false,"items":[{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"op":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Burt v. Bentsen","cite":"1994 WL 735377","y":1994,"court":"E.E.O.C. Apr. 29","by":{"0":"28"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Echazabal","cite":"536 U.S. 73","y":2002,"id":"2001/00-1406","sc":1,"sum":"The Court held that the ADA did not preclude the EEOC's regulation allowing the harm-to-self defense. The Court reasoned that deference applied to the regulation because it made sense of the statutory defense for qualification standards that are job-related and consistent with business necessity.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Counsel","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":2,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Dunn v. Commodity Futures Trading Comm’n","cite":"519 U.S. 465","y":1997,"id":"1996/95-1181","sc":1,"sum":"The Court ruled that the \"Treasury Amendment\" of the Commodity Exchange Act exempts from the Commodity Futures Trading Commission regulation off exchange trading in foreign currency options. \"The arguments favoring each side in the important public policy dispute over whether off exchange foreign currency options should be exempt from CEA regulation are best addressed to the Congress, not the Courts,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"DuPriest v. Bentsen","cite":"1994 WL 1755951","y":1994,"court":"E.E.O.C. May 2","by":{"0":"28"}},{"t":"case","label":"Edelman v. Lynchburg College","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"op":1,"sum":"The Court held that the EEOC's relation-back regulation was an unassailable interpretation of Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"H.J. Inc. v. Northwestern Bell Tel. Co.","cite":"492 U.S. 229","y":1989,"id":"1988/87-1252","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is Title IX of the Organized Crime Control Act of 1970 (OCCA), imposes criminal and civil liability upon persons who engage in certain \"prohibited activities,\" each of which is defined to include, as a necessary element, proof of a \"pattern of racketeering activity,\" § 1962. \"Racketeering activity\" means \"any act or threat …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Hazen Paper Co. v. Biggins","cite":"507 U.S. 604","y":1993,"id":"1992/91-1600","sc":1,"op":1,"sum":"The Supreme Court held that interfering with an employee’s pension does not automatically violate the ADEA, though it is a clear ERISA violation. While older employees may have more years of service, age and years of service are independent of each other. On remand, the court of appeals should reconsider whether there is sufficient evidence to support an ADEA violation independent of the pension interference.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"McDonald v. Sante Fe Trail Transp. Co.","cite":"427 U.S. 273","y":1976,"id":"1975/75-260","sc":1,"op":5,"sum":"Holding that Title VII protected whites discriminated against in favor of racial minorities.","sumSrc":"opinion","by":{"0":"16, 21"}},{"t":"case","label":"McDonnell Douglas Corp. v. Green","cite":"411 U.S. 792","y":1973,"id":"1972/72-490","sc":1,"sum":"The Court held that the findings of the EEOC could not bar a suit that meets the jurisdictional requirements for suing in federal district court. The Court also held that Congress meant to prevent discriminatory hiring practices, not guarantee jobs, so that the complainant in an employment discrimination lawsuit carries the initial burden to present a prima facie case for racial discrimination.","sumSrc":"Oyez","by":{"0":"20, 21"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"North Haven Bd. of Educ. v. Bell","cite":"456 U.S. 512","y":1982,"id":"1981/80-986","sc":1,"sum":"The Court held that, while Title IX does not expressly include employees, Congress’s choice of words, i.e. “no person” as opposed to “student” or “beneficiary”, implies an intention to broadly cover individuals involved in educational institutions rather than only students.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"O’Connor v. Consolidated Coin Caterers Corp.","cite":"517 U.S. 308","y":1996,"id":"1995/95-354","sc":1,"op":3,"sum":"Authored by Justice Antonin Scalia, the Court ruled that although the Age Discrimination in Employment Act of 1967 limits its protection to those who are 40 or older, it prohibits discrimination against those protected employees on the basis of age, not class membership. \"That one member of the protected class lost out to another member is irrelevant, so long as he lost out because of his age.","sumSrc":"Oyez","by":{"0":"17, 20, 22, 29"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"op":4,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"0":"15, 16, 26"}},{"t":"case","label":"Pittsburgh Press Co. v. Human Relations Comm’n","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Smiley v. Citibank (South Dakota), N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":1,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"TWA v. Thurston","cite":"469 U.S. 111","y":1985,"id":"1984/83-997","sc":1,"sum":"The Age Discrimination in Employment Act (ADEA) was amended in 1978 to prohibit the mandatory retirement of a protected employee because of his age. Concerned that its retirement policy, at least as it applied to flight engineers, violated the ADEA, petitioner Trans World Airlines (TWA) adopted a plan permitting any employee in \"flight engineer status\" at age 60 to continue working in that capacity. The plan, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":2,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"sum":"The term \"enterprise\" as used in RICO encompasses both legitimate and illegitimate enterprises.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"United States v. United Foods, Inc.","cite":"533 U.S. 405","y":2001,"id":"2000/00-276","sc":1,"sum":"The Court held that the assessment requirement violates the First Amendment.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Western Air Lines, Inc. v. Criswell","cite":"472 U.S. 400","y":1985,"id":"1984/83-1545","sc":1,"op":1,"sum":"The Age Discrimination in Employment Act of 1967 (ADEA) generally prohibits mandatory retirement before age 70, but §4(f)(1) of the Act provides an exception \"where age is a bona fide occupational qualification [BFOQ] reasonably necessary to the normal operation of the particular business.\" Petitioner airline company requires that its flight engineers, who are members of the cockpit crews of petitioners' aircraft …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"10"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","subs":["(a)(1)","(b)"],"stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":3,"sum":"Finding that \"older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs\".","sumSrc":"opinion","head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"29, 10, 12, 14, 15"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)","(a)(1)","(e)","(f)","(f)(1)","(f)(2)","(f)(2)(B)","(f)(2)(B)(i)","(l)","(l)(1)(A)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"10, 11, passim, 5, 10, 11, 5, 11, 12, 23, 24, 23, 6, 7, 12, 13, 22, 23, 24, 25, 6, 13, 4, 13, 28"}},{"t":"usc","label":"29 U.S.C. § 625","url":"https://www.law.cornell.edu/uscode/text/29/625","by":{"0":"1, 26"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","by":{"0":"1, 26"}},{"t":"usc","label":"29 U.S.C. § 628","url":"https://www.law.cornell.edu/uscode/text/29/628","stext":{"head":"§628. Rules and regulations; exemptions","paras":[[0,"In accordance with the provisions of subchapter II of chapter 5 of title 5, the Equal Employment Opportunity Commission may issue such rules and regulations as it may consider necessary or appropriate for carrying out this chapter, and may establish such reasonable exemptions to and from any or all provisions of this chapter as it may find necessary and proper in the public interest."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/628?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§628. Rules and regulations; exemptions","tname":"Labor","by":{"0":"1, 26"}},{"t":"usc","label":"29 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/29/631","subs":["(a)"],"stext":{"head":"§631. Age limits","paras":[[0,"(a) Individuals at least 40 years of age"],[0,"The prohibitions in this chapter shall be limited to individuals who are at least 40 years of age."],[0,"(b) Employees or applicants for employment in Federal Government"],[0,"In the case of any personnel action affecting employees or applicants for employment which is subject to the provisions of section 633a of this title, the prohibitions established in section 633a of this title shall be limited to individuals who are at least 40 years of age."],[0,"(c) Bona fide executives or high policymakers"],[0,"(1) Nothing in this chapter shall be construed to prohibit compulsory retirement of any employee who has attained 65 years of age and who, for the 2-year period immediately before retirement, is employed in a bona fide executive or a high policymaking position, if such employee is entitled to an immediate nonforfeitable annual retirement benefit from a pension, profit-sharing, savings, or deferred compensation plan, or any combination of such plans, of the employer of such employee, which equals, in the aggregate, at least $44,000."],[0,"(2) In applying the retirement benefit test of paragraph (1) of this subsection, if any such retirement benefit is in a form other than a straight life annuity (with no ancillary benefits), or if employees contribute to any such plan or make rollover contributions, such benefit shall be adjusted in accordance with regulations prescribed by the Equal Employment Opportunity Commission, after consultation with the Secretary of the Treasury, so that the benefit is the equivalent of a straight life annuity (with no ancillary benefits) under a plan to which employees do not contribute and under which no rollover contributions are made."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/631?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§631. Age limits","tname":"Labor","by":{"0":"4, 5, 8, 15, 2, 3"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(b)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§633a. Nondiscrimination on account of age in Federal Government employment","tname":"Labor","by":{"0":"29, 27"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"6, 16, 21"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"42"}},{"t":"law","label":"Older Workers Benefit Protection Act, Pub. L. No. 101-433","url":"https://www.govinfo.gov/link/statute/104/978","by":{"0":"22"}}]};